function formatPrice(price) {
  return price.toLocaleString() + '원';
}

function ProductCard({ product, formatPrice, badge }) {
  return (
    <article>
      <h2>{product.name} {badge}</h2>
      <p>{formatPrice(product.price)}</p>
    </article>
  );
}

const product = { name: '파란 셔츠', price: 39000 };

ReactDOM.createRoot(document.querySelector('#root')).render(
  <ProductCard
    product={product}
    formatPrice={formatPrice}
    badge={<span className="badge">신상품</span>}
  />
);

